function safeJson(value) {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

export function getNextMigrationFiles({ projectName, profile, analysis = null, designTemplate = null }) {
  const config = safeJson({ name: projectName, profile, analysis, design: designTemplate });
  const files = {
    'package.json': JSON.stringify({
      name: projectName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'migrated-web',
      private: true,
      scripts: { dev: 'next dev', build: 'next build', start: 'next start' },
      dependencies: { '@vercel/postgres': '^0.10.0', 'midtrans-client': '^1.4.2', next: '^15.2.0', react: '^19.0.0', 'react-dom': '^19.0.0' },
      engines: { node: '>=18.18.0' }
    }, null, 2),
    'app/layout.js': `import './globals.css';\n\nexport const metadata = { title: '${projectName.replace(/'/g, "\\'")}', description: 'Migrasi Next.js dari GAS Web App' };\n\nexport default function RootLayout({ children }) { return <html lang="id"><body>{children}</body></html>; }\n`,
    'lib/app-config.js': `export const APP = ${config};\n`,
    'app/page.js': `'use client';\n\nimport { useEffect, useMemo, useState } from 'react';\nimport { APP } from '../lib/app-config';\n\nconst key = 'migrated-next-records';\nconst empty = value => value === '' || value === null || value === undefined ? '-' : value;\n\nexport default function Home() {\n  const modules = APP.profile.modules || [];\n  const [user, setUser] = useState(null);\n  const [activeId, setActiveId] = useState(modules[0]?.id || 'utama');\n  const [records, setRecords] = useState([]);\n  const [theme, setTheme] = useState('dark');\n  const active = useMemo(() => modules.find(item => item.id === activeId) || modules[0], [activeId, modules]);\n  useEffect(() => { try { setRecords(JSON.parse(localStorage.getItem(key) || '[]')); } catch {} }, []);\n  useEffect(() => { document.documentElement.dataset.theme = theme; }, [theme]);\n  const visible = records.filter(item => item.moduleId === active?.id).slice().reverse();\n  function login(event) { event.preventDefault(); const data = new FormData(event.currentTarget); if (!data.get('username') || !data.get('password')) return; setUser({ name: data.get('username') === 'Admin' ? 'Administrator' : data.get('username'), role: data.get('username') === 'Admin' ? 'admin' : 'member' }); }\n  function save(event) { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); const next = [{ id: crypto.randomUUID(), moduleId: active.id, createdAt: new Date().toLocaleString('id-ID'), ...values }, ...records]; setRecords(next); localStorage.setItem(key, JSON.stringify(next)); event.currentTarget.reset(); }\n  if (!user) return <main className="login"><section className="hero"><p>{APP.profile.name}</p><h1>{APP.name}</h1><span>{APP.profile.tagline}</span></section><form className="login-card" onSubmit={login}><p className="eyebrow">NEXT.JS MIGRATION</p><h2>Selamat datang</h2><p>Masuk untuk membuka dashboard.</p><input name="username" placeholder="Username" defaultValue="Admin" required/><input name="password" type="password" placeholder="Password" required/><button>Masuk ke Dashboard</button><small>Demo lokal: Admin / Admin123</small></form></main>;\n  return <main className="shell"><aside><div className="brand"><b>{APP.name}</b><span>{APP.profile.name}</span></div><nav>{modules.filter(item => !item.adminOnly || user.role === 'admin').map(item => <button key={item.id} className={activeId === item.id ? 'active' : ''} onClick={() => setActiveId(item.id)}>{item.name}</button>)}</nav><div className="account"><b>{user.name}</b><span>{user.role === 'admin' ? 'Administrator' : 'User'}</span><button onClick={() => setUser(null)}>Keluar</button></div></aside><section className="workspace"><header><div><p className="eyebrow">{APP.profile.name}</p><h1>{active?.name}</h1><span>Versi Next.js hasil migrasi dari proyek GAS.</span></div><div className="header-actions"><button className="theme" onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>{theme === 'dark' ? 'Terang' : 'Gelap'}</button><div className="stat"><small>Total {active?.name}</small><b>{visible.length}</b></div></div></header><div className="grid"><form className="panel" onSubmit={save}><h2>Tambah {active?.name}</h2>{active?.fields.map(field => <label key={field.key}>{field.label}{field.type === 'select' ? <select name={field.key} required>{field.options.map(option => <option key={option}>{option}</option>)}</select> : <input name={field.key} type={field.type === 'datetime-local' ? 'datetime-local' : field.type} required/>}</label>)}<button>Simpan Data</button></form><section className="panel table-panel"><h2>{active?.name} terbaru</h2><div className="table-wrap"><table><thead><tr>{(active?.fields || []).map(field => <th key={field.key}>{field.label}</th>)}<th>Dibuat</th></tr></thead><tbody>{visible.length ? visible.map(row => <tr key={row.id}>{(active?.fields || []).map(field => <td key={field.key}>{empty(row[field.key])}</td>)}<td>{row.createdAt}</td></tr>) : <tr><td colSpan={(active?.fields?.length || 0) + 1}>Belum ada data.</td></tr>}</tbody></table></div></section></div><p className="notice">Data versi awal ini disimpan di browser. Sambungkan database produksi melalui API Next.js sebelum digunakan oleh banyak pengguna.</p></section></main>;\n}\n`,
    'app/globals.css': `:root{--bg:#0b1220;--surface:#121c30;--surface2:#192842;--text:#edf3ff;--muted:#9eb0cf;--line:#324564;--accent:#3b82f6}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 5%,#1d4ed833,transparent 28rem),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui}button,input,select{font:inherit}.login{min-height:100vh;display:grid;grid-template-columns:1.2fr .8fr}.hero{padding:clamp(2rem,7vw,7rem);display:flex;flex-direction:column;justify-content:center;background:linear-gradient(145deg,#0f274b,#1d4ed8,#38bdf8);animation:glow 16s ease infinite;background-size:180% 180%}.hero p,.eyebrow{font-size:.75rem;font-weight:800;letter-spacing:.12em}.hero h1{font-size:clamp(3rem,7vw,6rem);margin:.5rem 0}.hero span{max-width:34rem;color:#dbeafe;font-size:1.1rem;line-height:1.7}.login-card{align-self:center;width:min(26rem,calc(100% - 3rem));margin:auto;padding:2rem;border:1px solid var(--line);border-radius:1.5rem;background:var(--surface);box-shadow:0 25px 70px #0005;animation:rise .55s ease both}.login-card h2{font-size:2rem;margin:.3rem 0}.login-card p,.login-card small,.workspace header span,.notice{color:var(--muted)}input,select{width:100%;margin:.45rem 0 1rem;padding:.8rem .9rem;border:1px solid var(--line);border-radius:.75rem;background:#0d1729;color:var(--text)}button{border:0;border-radius:.75rem;padding:.8rem 1rem;background:var(--accent);color:white;font-weight:700;cursor:pointer;transition:transform .18s ease,filter .18s ease}button:hover{transform:translateY(-2px);filter:brightness(1.1)}.shell{min-height:100vh;display:flex}aside{width:17rem;padding:1.25rem;background:#0d1729;border-right:1px solid var(--line);display:flex;flex-direction:column}.brand{display:grid;gap:.3rem;padding:.8rem}.brand span,.account span{color:var(--muted);font-size:.85rem}nav{display:grid;gap:.35rem;margin-top:2rem}nav button{background:transparent;text-align:left;color:#cbd8ef}nav button.active,nav button:hover{background:var(--surface2)}.account{display:grid;gap:.35rem;margin-top:auto;padding:.8rem;border-top:1px solid var(--line)}.account button{margin-top:.6rem;background:transparent;border:1px solid var(--line)}.workspace{flex:1;padding:clamp(1rem,3vw,3rem)}header{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start;margin-bottom:2rem}header h1{margin:.25rem 0;font-size:clamp(2rem,4vw,3rem)}.header-actions{display:flex;gap:.8rem;align-items:center}.theme{background:var(--surface2)}.stat{min-width:9rem;padding:1rem;border:1px solid var(--line);border-radius:1rem;background:var(--surface)}.stat small{display:block;color:var(--muted)}.stat b{display:block;font-size:2rem;color:#60a5fa}.grid{display:grid;grid-template-columns:minmax(18rem,.8fr) minmax(0,1.6fr);gap:1.25rem}.panel{padding:1.5rem;background:var(--surface);border:1px solid var(--line);border-radius:1.25rem}.panel h2{margin-top:0}label{display:block;margin:.9rem 0;font-size:.9rem;font-weight:700}.table-wrap{overflow:auto}table{width:100%;min-width:40rem;border-collapse:collapse}th,td{padding:1rem;text-align:left;border-bottom:1px solid var(--line);font-size:.9rem}th{color:var(--muted);font-size:.75rem;text-transform:uppercase}.notice{margin-top:1rem;font-size:.85rem}@keyframes glow{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@media(max-width:800px){.login{grid-template-columns:1fr}.hero{min-height:38vh}.shell{display:block}aside{width:100%;min-height:auto}nav{display:flex;overflow:auto;margin:1rem 0}.account{display:none}.grid{grid-template-columns:1fr}header{display:block}.header-actions{margin-top:1rem}}\n`,
    '.gitignore': 'node_modules/\n.next/\n.vercel/\n.env*\n',
    'README.md': `# ${projectName} — Next.js migration\n\nMigrasi awal dari proyek Google Apps Script. UI dan modul sudah dipindahkan ke Next.js; data versi awal disimpan di browser agar proyek dapat langsung di-deploy.\n\n## Jalankan\n\n\`\`\`bash\nnpm install\nnpm run dev\n\`\`\`\n\n## Deploy Vercel\n\n\`\`\`bash\nnpx vercel --prod\n\`\`\`\n\n## Produksi\n\nUntuk data bersama, login yang aman, dan migrasi data Google Sheets, sambungkan database (misalnya Postgres/Supabase) melalui Route Handlers Next.js. Jangan menyimpan kredensial Google atau data produksi di client/browser.\n`
  };
  return { ...files, 'app/layout.js': getEnhancedNextLayout(projectName, profile, analysis), 'app/pwa-register.js': getPwaRegister(), 'app/page.js': personalizePaymentPage(personalizeMarketingPage(getPremiumNextPage())), 'app/globals.css': getEnhancedNextStyles(designTemplate) + getLandingPolishStyles() + getDesignTemplateStyles(designTemplate) + getMarketingLandingStyles() + getAiLandingVariantStyles(), 'public/manifest.webmanifest': getPwaManifest(projectName, profile, designTemplate), 'public/sw.js': getPwaServiceWorker(), 'public/icon.svg': getPwaIcon(projectName, designTemplate), 'lib/database.js': getDatabaseAdapter(), 'lib/payment/midtrans.js': getMidtransAdapter(), 'lib/payment/index.js': getPaymentAdapter(), 'lib/notify/telegram.js': getTelegramAdapter(), 'lib/notify/whatsapp.js': getWhatsappAdapter(), 'lib/notify/index.js': getNotifyAdapter(), 'lib/secret-crypto.js': getSecretCrypto(), 'lib/admin.js': getAdminGuard(), 'components/PaymentButton.jsx': getPaymentButton(), 'components/NotificationSettings.jsx': getNotificationSettings(), 'app/api/records/route.js': getRecordsApi(), 'app/api/payment/create-transaction/route.js': getCreateTransactionApi(), 'app/api/payment/webhook/route.js': getPaymentWebhookApi(), 'app/api/notification-settings/route.js': getNotificationSettingsApi(), 'app/api/notification-settings/test/route.js': getNotificationTestApi(), 'db/schema.sql': getDatabaseSchema(), 'DATABASE.md': getDatabaseGuide(), 'PAYMENT_GATEWAY.md': getPaymentGatewayGuide(), '.env.example': getPaymentEnvExample(), 'MIGRATION_AUDIT.md': getMigrationAudit(projectName, profile, analysis, designTemplate), 'PWA.md': getPwaGuide() };
}

function getPaymentEnvExample() { return `# Midtrans Snap (default). Jangan pernah expose SERVER_KEY ke browser.\nMIDTRANS_SERVER_KEY=\nMIDTRANS_CLIENT_KEY=\nMIDTRANS_IS_PRODUCTION=false\nPAYMENT_PROVIDER=midtrans\n# Notifikasi: telegram | whatsapp | none\nNOTIFICATION_CHANNEL=telegram\nFONNTE_TOKEN=\nFONNTE_TARGET_NUMBER=\nTELEGRAM_BOT_TOKEN=\nTELEGRAM_CHAT_ID=\n# Wajib untuk menyimpan token notifikasi terenkripsi di database (base64, 32 byte)\nNOTIFICATION_ENCRYPTION_KEY=\n# Token khusus admin untuk membuka Pengaturan Notifikasi (tidak pernah disimpan di UI)\nADMIN_SETTINGS_TOKEN=\nAPP_BASE_URL=https://your-app.vercel.app\n`; }
function getPaymentGatewayGuide() { return `# Midtrans Snap & Notifikasi\n\nGateway default adalah **Midtrans Snap**. Isi secret di Vercel Environment Variables, lalu deploy. Client key boleh dipakai browser hanya untuk memuat Snap; server key dan token notifikasi tidak pernah masuk source client.\n\n1. Isi \`MIDTRANS_SERVER_KEY\`, \`MIDTRANS_CLIENT_KEY\`, lalu pilih sandbox/production.\n2. Daftarkan webhook Midtrans ke \`/api/payment/webhook\`. Endpoint memverifikasi SHA-512 signature dan idempoten.\n3. Jalankan \`db/schema.sql\` sebelum menerima pembayaran.\n4. Untuk notifikasi, set channel env sebagai fallback atau buka menu **Pengaturan Notifikasi** dengan \`ADMIN_SETTINGS_TOKEN\`; token tersimpan terenkripsi dan hanya ditampilkan tersamarkan.\n\nCheckout gagal secara aman jika environment belum lengkap; build tetap berhasil tanpa credential. Uji dahulu di Midtrans Sandbox sebelum production.\n`; }
function getMidtransAdapter() { return `import midtransClient from 'midtrans-client';\nimport crypto from 'crypto';\nconst enabled=()=>process.env.PAYMENT_PROVIDER!=='manual';\nconst snap=()=>new midtransClient.Snap({isProduction:process.env.MIDTRANS_IS_PRODUCTION==='true',serverKey:process.env.MIDTRANS_SERVER_KEY,clientKey:process.env.MIDTRANS_CLIENT_KEY});\nexport function getSnapUrl(){return process.env.MIDTRANS_IS_PRODUCTION==='true'?'https://app.midtrans.com/snap/snap.js':'https://app.sandbox.midtrans.com/snap/snap.js'}\nexport async function createMidtransTransaction({orderId,amount,customer={}}){if(!enabled())throw new Error('Payment provider belum aktif.');if(!process.env.MIDTRANS_SERVER_KEY||!process.env.MIDTRANS_CLIENT_KEY)throw new Error('Konfigurasi Midtrans belum lengkap.');const gross_amount=Math.round(Number(amount));if(!Number.isSafeInteger(gross_amount)||gross_amount<=0)throw new Error('Nominal pembayaran tidak valid.');const tx=await snap().createTransaction({transaction_details:{order_id:orderId,gross_amount},customer_details:{first_name:String(customer.name||'Pelanggan').slice(0,80),email:customer.email||undefined,phone:customer.phone||undefined}});return{token:tx.token,redirectUrl:tx.redirect_url,clientKey:process.env.MIDTRANS_CLIENT_KEY,snapUrl:getSnapUrl()};}\nexport function verifyMidtransSignature(payload){const expected=crypto.createHash('sha512').update(String(payload.order_id||'')+String(payload.status_code||'')+String(payload.gross_amount||'')+String(process.env.MIDTRANS_SERVER_KEY||'')).digest('hex');const supplied=String(payload.signature_key||'');return supplied.length===expected.length&&crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(supplied));}\nexport const normalizePaymentStatus=p=>['settlement','capture'].includes(p.transaction_status)&&(!p.fraud_status||p.fraud_status==='accept')?'paid':p.transaction_status==='expire'?'expired':p.transaction_status==='cancel'?'cancelled':p.transaction_status==='deny'?'failed':'pending';\n`; }
function getPaymentAdapter() { return `import { createMidtransTransaction } from './midtrans';\nexport async function createPayment(input){return createMidtransTransaction(input);}\n`; }
function getSecretCrypto() { return `import crypto from 'crypto';\nconst key=()=>{const raw=process.env.NOTIFICATION_ENCRYPTION_KEY;if(!raw)throw new Error('NOTIFICATION_ENCRYPTION_KEY belum diatur.');const value=Buffer.from(raw,'base64');if(value.length!==32)throw new Error('NOTIFICATION_ENCRYPTION_KEY harus base64 32 byte.');return value};\nexport function encryptSecret(value){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',key(),iv);const body=Buffer.concat([cipher.update(String(value),'utf8'),cipher.final()]);return [iv.toString('base64'),cipher.getAuthTag().toString('base64'),body.toString('base64')].join('.')}\nexport function decryptSecret(value){const [iv,tag,body]=String(value||'').split('.');const decipher=crypto.createDecipheriv('aes-256-gcm',key(),Buffer.from(iv,'base64'));decipher.setAuthTag(Buffer.from(tag,'base64'));return Buffer.concat([decipher.update(Buffer.from(body,'base64')),decipher.final()]).toString('utf8')}\nexport const maskSecret=value=>value?'••••••'+String(value).slice(-4):'';\n`; }
function getAdminGuard() { return `export function assertAdmin(request){const expected=process.env.ADMIN_SETTINGS_TOKEN;const supplied=request.headers.get('x-admin-settings-token');if(!expected||!supplied||supplied!==expected)throw new Error('Akses admin tidak sah. Masukkan ADMIN_SETTINGS_TOKEN.');}\n`; }

function getDatabaseGuide() {
  return `# Database produksi\n\nProyek ini memiliki API data dan adapter PostgreSQL berbasis \`@vercel/postgres\`.\n\n1. Buat atau hubungkan Vercel Postgres pada proyek Vercel Anda.\n2. Pastikan environment variable \`POSTGRES_URL\` tersedia pada Production dan Preview.\n3. Jalankan isi \`db/schema.sql\` sekali pada database tersebut.\n4. Deploy ulang. Aplikasi otomatis memakai API database; tanpa \`POSTGRES_URL\`, aplikasi memakai penyimpanan browser sebagai fallback demo satu pengguna.\n\nJangan menyimpan URL database atau secret di source code.\n`;
}

function getDatabaseSchema() {
  return `-- Jalankan pada Vercel Postgres / PostgreSQL sebelum produksi.\nCREATE TABLE IF NOT EXISTS app_records (\n  id TEXT PRIMARY KEY,\n  module_id TEXT NOT NULL,\n  payload JSONB NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS app_records_module_created_idx ON app_records (module_id, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS payment_transactions (\n  order_id TEXT PRIMARY KEY, record_id TEXT NOT NULL, module_id TEXT NOT NULL,\n  gross_amount BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', provider TEXT NOT NULL DEFAULT 'midtrans',\n  raw_payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS payment_transactions_record_idx ON payment_transactions (record_id);\n\nCREATE TABLE IF NOT EXISTS notification_settings (\n  id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id), channel TEXT NOT NULL DEFAULT 'none', token_ciphertext TEXT, target TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n`;
}

function getDatabaseAdapter() {
  return `import { sql } from '@vercel/postgres';\n\nexport const databaseReady = () => Boolean(process.env.POSTGRES_URL);\n\nexport async function listRecords() {\n  if (!databaseReady()) return null;\n  await sql\`CREATE TABLE IF NOT EXISTS app_records (id TEXT PRIMARY KEY, module_id TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\`;\n  const { rows } = await sql\`SELECT id, module_id, payload, created_at FROM app_records ORDER BY created_at DESC LIMIT 500\`;\n  return rows.map(row => ({ id: row.id, moduleId: row.module_id, createdAt: new Date(row.created_at).toLocaleString('id-ID'), ...row.payload }));\n}\n\nexport async function insertRecord(record) {\n  if (!databaseReady()) return null;\n  await sql\`CREATE TABLE IF NOT EXISTS app_records (id TEXT PRIMARY KEY, module_id TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\`;\n  const { id, moduleId, createdAt, ...payload } = record;\n  await sql\`INSERT INTO app_records (id, module_id, payload) VALUES (\${id}, \${moduleId}, \${JSON.stringify({ ...payload, createdAt })}::jsonb)\`;\n  return record;\n}\n`;
}

function getRecordsApi() {
  return `import { NextResponse } from 'next/server';\nimport { databaseReady, insertRecord, listRecords } from '../../../lib/database';\nimport { sendNotification } from '../../../lib/notify';\nexport const dynamic = 'force-dynamic';\nexport async function GET(){if(!databaseReady())return NextResponse.json({configured:false,records:[]});return NextResponse.json({configured:true,records:await listRecords()});}\nexport async function POST(request){if(!databaseReady())return NextResponse.json({configured:false,error:'Database belum dikonfigurasi.'},{status:503});const record=await request.json();if(!record||typeof record.id!=='string'||typeof record.moduleId!=='string'||record.id.length>100||record.moduleId.length>80)return NextResponse.json({error:'Data tidak valid.'},{status:400});await insertRecord(record);sendNotification({title:'Data baru tercatat',message:'Modul '+record.moduleId+' menerima data baru.',type:'record_created',reference:record.id}).catch(error=>console.error('Notification record gagal:',error.message));return NextResponse.json({configured:true,record},{status:201});}\n`;
}

function getTelegramAdapter() { return `export async function sendTelegram({token,target,message}){if(!token||!target)return{sent:false,reason:'Telegram belum dikonfigurasi'};const response=await fetch('https://api.telegram.org/bot'+token+'/sendMessage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:target,text:message,disable_web_page_preview:true})});if(!response.ok)throw new Error('Telegram mengembalikan HTTP '+response.status);return{sent:true};}\n`; }
function getWhatsappAdapter() { return `export async function sendWhatsapp({token,target,message}){if(!token||!target)return{sent:false,reason:'WhatsApp belum dikonfigurasi'};const response=await fetch('https://api.fonnte.com/send',{method:'POST',headers:{Authorization:token,'Content-Type':'application/json'},body:JSON.stringify({target,message,countryCode:'62'})});if(!response.ok)throw new Error('Fonnte mengembalikan HTTP '+response.status);return{sent:true};}\n`; }
function getNotifyAdapter() { return `import { sql } from '@vercel/postgres';\nimport { decryptSecret } from '../secret-crypto';\nimport { sendTelegram } from './telegram';\nimport { sendWhatsapp } from './whatsapp';\nconst dbReady=()=>Boolean(process.env.POSTGRES_URL);\nasync function configured(){let setting=null;if(dbReady()){try{const result=await sql\`SELECT channel,token_ciphertext,target FROM notification_settings WHERE id=TRUE\`;setting=result.rows[0]||null}catch{}}const channel=setting?.channel||process.env.NOTIFICATION_CHANNEL||'none';let token='';try{token=setting?.token_ciphertext?decryptSecret(setting.token_ciphertext):channel==='telegram'?process.env.TELEGRAM_BOT_TOKEN:process.env.FONNTE_TOKEN}catch{token=''}const target=setting?.target||(channel==='telegram'?process.env.TELEGRAM_CHAT_ID:process.env.FONNTE_TARGET_NUMBER)||'';return{channel,token,target}}\nexport async function sendNotification({title,message,type='event',reference=''}){try{const c=await configured();if(c.channel==='none')return{sent:false,reason:'disabled'};const text=['*'+title+'*',message,reference?'Referensi: '+reference:''].filter(Boolean).join('\\n');if(c.channel==='telegram')return await sendTelegram({...c,message:text});if(c.channel==='whatsapp')return await sendWhatsapp({...c,message:text});return{sent:false,reason:'channel_invalid'}}catch(error){console.error('Notifikasi gagal:',error.message);return{sent:false,reason:'failed'}}}\n`; }
function getCreateTransactionApi() { return `import { NextResponse } from 'next/server';\nimport { sql } from '@vercel/postgres';\nimport { databaseReady } from '../../../../lib/database';\nimport { createPayment } from '../../../../lib/payment';\nexport async function POST(request){try{if(!databaseReady())return NextResponse.json({error:'Database belum dikonfigurasi.'},{status:503});const body=await request.json();const amount=Math.round(Number(body.amount));if(typeof body.recordId!=='string'||!body.recordId||!Number.isSafeInteger(amount)||amount<=0)return NextResponse.json({error:'Data pembayaran tidak valid.'},{status:400});const orderId='PAY-'+body.recordId+'-'+Date.now();const payment=await createPayment({orderId,amount,customer:body.customer||{}});await sql\`INSERT INTO payment_transactions(order_id,record_id,module_id,gross_amount,status,provider) VALUES(\${orderId},\${body.recordId},\${String(body.moduleId||'utama')},\${amount},'pending','midtrans')\`;return NextResponse.json({orderId,token:payment.token,snapUrl:payment.snapUrl,clientKey:payment.clientKey},{status:201});}catch(error){return NextResponse.json({error:error.message||'Checkout gagal.'},{status:400});}}\n`; }
function getPaymentWebhookApi() { return `import { NextResponse } from 'next/server';\nimport { sql } from '@vercel/postgres';\nimport { normalizePaymentStatus, verifyMidtransSignature } from '../../../../lib/payment/midtrans';\nimport { sendNotification } from '../../../../lib/notify';\nexport async function POST(request){try{const payload=await request.json();if(!verifyMidtransSignature(payload))return NextResponse.json({error:'Signature Midtrans tidak sah.'},{status:401});const status=normalizePaymentStatus(payload);const result=await sql\`UPDATE payment_transactions SET status=\${status},raw_payload=\${JSON.stringify(payload)}::jsonb,updated_at=NOW() WHERE order_id=\${String(payload.order_id)} AND status IS DISTINCT FROM \${status} RETURNING order_id,record_id,gross_amount\`;const changed=result.rows[0];if(changed&&status==='paid'){await sql\`UPDATE app_records SET payload=payload || jsonb_build_object('statusPembayaran','Lunas') WHERE id=\${changed.record_id}\`;sendNotification({title:'Pembayaran berhasil',message:'Pembayaran '+changed.order_id+' sebesar Rp '+changed.gross_amount+' telah diterima.',type:'payment_paid',reference:changed.order_id}).catch(error=>console.error('Notification pembayaran gagal:',error.message));}return NextResponse.json({received:true,orderId:payload.order_id,status,idempotent:!changed});}catch(error){return NextResponse.json({error:'Webhook tidak dapat diproses.'},{status:400});}}\n`; }
function getNotificationSettingsApi() { return `import { NextResponse } from 'next/server';\nimport { sql } from '@vercel/postgres';\nimport { assertAdmin } from '../../../lib/admin';\nimport { encryptSecret,maskSecret } from '../../../lib/secret-crypto';\nexport async function GET(request){try{assertAdmin(request);const result=await sql\`SELECT channel,token_ciphertext,target,updated_at FROM notification_settings WHERE id=TRUE\`;const row=result.rows[0];return NextResponse.json({channel:row?.channel||process.env.NOTIFICATION_CHANNEL||'none',target:row?.target||'',tokenMasked:maskSecret(row?.token_ciphertext?'saved':'')});}catch(error){return NextResponse.json({error:error.message},{status:401});}}\nexport async function PUT(request){try{assertAdmin(request);const body=await request.json();if(!['none','telegram','whatsapp'].includes(body.channel))return NextResponse.json({error:'Channel tidak valid.'},{status:400});const token=body.token?encryptSecret(body.token):null;await sql\`INSERT INTO notification_settings(id,channel,token_ciphertext,target,updated_at) VALUES(TRUE,\${body.channel},\${token},\${String(body.target||'')},NOW()) ON CONFLICT(id) DO UPDATE SET channel=EXCLUDED.channel,token_ciphertext=COALESCE(EXCLUDED.token_ciphertext,notification_settings.token_ciphertext),target=EXCLUDED.target,updated_at=NOW()\`;return NextResponse.json({saved:true});}catch(error){return NextResponse.json({error:error.message||'Pengaturan gagal disimpan.'},{status:400});}}\n`; }
function getNotificationTestApi() { return `import { NextResponse } from 'next/server';\nimport { assertAdmin } from '../../../../lib/admin';\nimport { sendNotification } from '../../../../lib/notify';\nexport async function POST(request){try{assertAdmin(request);const result=await sendNotification({title:'Tes notifikasi',message:'Koneksi notifikasi aplikasi berhasil diuji.',type:'test'});return NextResponse.json(result);}catch(error){return NextResponse.json({error:error.message},{status:401});}}\n`; }
function getPaymentButton() { return `'use client';\nimport { useState } from 'react';\nexport default function PaymentButton({recordId,moduleId,amount,customer={}}){const [busy,setBusy]=useState(false);const [error,setError]=useState('');async function pay(){setBusy(true);setError('');try{const response=await fetch('/api/payment/create-transaction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordId,moduleId,amount,customer})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Pembayaran gagal dibuat.');await new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-midtrans-snap]');const open=()=>window.snap?window.snap.pay(data.token,{onSuccess:resolve,onPending:resolve,onError:reject,onClose:resolve}):reject(new Error('Snap tidak tersedia.'));if(existing){open();return}const script=document.createElement('script');script.src=data.snapUrl;script.dataset.midtransSnap='true';script.setAttribute('data-client-key',data.clientKey);script.onload=open;script.onerror=()=>reject(new Error('Skrip Snap gagal dimuat.'));document.body.appendChild(script);});}catch(err){setError(err.message)}finally{setBusy(false)}}return <span className="payment-action"><button type="button" onClick={pay} disabled={busy}>{busy?'Memuat…':'Bayar'}</button>{error&&<small role="alert">{error}</small>}</span>}\n`; }
function getNotificationSettings() { return `'use client';\nimport { useState } from 'react';\nexport default function NotificationSettings(){const [adminToken,setAdminToken]=useState('');const [channel,setChannel]=useState('telegram');const [target,setTarget]=useState('');const [token,setToken]=useState('');const [message,setMessage]=useState('');const headers=()=>({'Content-Type':'application/json','x-admin-settings-token':adminToken});async function load(){const r=await fetch('/api/notification-settings',{headers:headers()});const d=await r.json();if(!r.ok)return setMessage(d.error||'Akses ditolak.');setChannel(d.channel);setTarget(d.target);setMessage(d.tokenMasked?'Token tersimpan aman dan disamarkan.':'Belum ada token tersimpan.')}async function save(e){e.preventDefault();const r=await fetch('/api/notification-settings',{method:'PUT',headers:headers(),body:JSON.stringify({channel,target,token})});const d=await r.json();setMessage(r.ok?'Pengaturan disimpan.':d.error||'Gagal menyimpan.');if(r.ok)setToken('')}async function test(){const r=await fetch('/api/notification-settings/test',{method:'POST',headers:headers()});const d=await r.json();setMessage(d.sent?'Notifikasi tes terkirim.':(d.error||d.reason||'Notifikasi belum terkirim.'))}return <section className="panel notification-settings"><p className="eyebrow">ADMIN ONLY</p><h2>Pengaturan Notifikasi</h2><p>Token dikirim ke server hanya saat disimpan dan tidak akan ditampilkan kembali.</p><form onSubmit={save}><label>ADMIN_SETTINGS_TOKEN<input type="password" value={adminToken} onChange={e=>setAdminToken(e.target.value)} required/></label><div className="inline-actions"><button type="button" className="ghost" onClick={load}>Muat pengaturan</button></div><label>Channel<select value={channel} onChange={e=>setChannel(e.target.value)}><option value="telegram">Telegram</option><option value="whatsapp">WhatsApp (Fonnte)</option><option value="none">Nonaktif</option></select></label><label>{channel==='telegram'?'Chat ID Telegram':'Nomor WhatsApp'}<input value={target} onChange={e=>setTarget(e.target.value)} placeholder={channel==='telegram'?'-100...':'628...'} /></label><label>Token baru <small>(kosongkan agar token lama dipakai)</small><input type="password" value={token} onChange={e=>setToken(e.target.value)} /></label><div className="inline-actions"><button>Simpan</button><button type="button" className="ghost" onClick={test}>Kirim tes</button></div>{message&&<p className="notice">{message}</p>}</form></section>}\n`; }

function personalizePaymentPage(source) {
  return source
    .replace("import { APP } from '../lib/app-config';", "import { APP } from '../lib/app-config';\\nimport PaymentButton from '../components/PaymentButton';\\nimport NotificationSettings from '../components/NotificationSettings';")
    .replace("const active = modules.find(item => item.id === view);", "const active = modules.find(item => item.id === view);\\n  const recordAmount = row => Number(row.total||row.nominal||row.harga||row.biaya||0);")
    .replace("<button className={view==='dashboard'?'active':''} onClick={()=>setView('dashboard')}>Dashboard</button>{nav.map", "<button className={view==='dashboard'?'active':''} onClick={()=>setView('dashboard')}>Dashboard</button>{nav.map")
    .replace("}</nav><div className=\"account\">", "}</nav>{user.role==='admin'&&<button className={view==='notification-settings'?'active':''} onClick={()=>setView('notification-settings')}>Pengaturan Notifikasi</button>}<div className=\"account\">")
    .replace("{!active?<Dashboard rows={rows} total={total} modules={modules} setView={setView}/>:<Module active={active} rows={rows.filter(row=>row.moduleId===active.id)} save={save}/>}", "{view==='notification-settings'?<NotificationSettings/>:!active?<Dashboard rows={rows} total={total} modules={modules} setView={setView}/>:<Module active={active} rows={rows.filter(row=>row.moduleId===active.id)} save={save} recordAmount={recordAmount}/>}")
    .replace("{!active?<Dashboard rows={rows} income={income} byModule={byModule} setView={setView}/>:<Module active={active} rows={rows.filter(r=>r.moduleId===active.id)} save={save}/>}", "{view==='notification-settings'?<NotificationSettings/>:!active?<Dashboard rows={rows} income={income} byModule={byModule} setView={setView}/>:<Module active={active} rows={rows.filter(r=>r.moduleId===active.id)} save={save} recordAmount={recordAmount}/>} ")
    .replace("function Module({active,rows,save}) {", "function Module({active,rows,save,recordAmount}) {")
    .replace("function Module({active,rows,save}){", "function Module({active,rows,save,recordAmount}){")
    .replace("<th>Dibuat</th></tr>", "<th>Dibuat</th><th>Pembayaran</th></tr>")
    .replace("<td>{row.createdAt}</td></tr>", "<td>{row.createdAt}</td><td>{recordAmount(row)>0?<PaymentButton recordId={row.id} moduleId={active.id} amount={recordAmount(row)} customer={{name:row.nama||row.pelanggan||row.nama_pelanggan}}/>:'-'}</td></tr>")
    .replace("<td>{r.createdAt}</td></tr>", "<td>{r.createdAt}</td><td>{recordAmount(r)>0?<PaymentButton recordId={r.id} moduleId={active.id} amount={recordAmount(r)} customer={{name:r.nama||r.pelanggan||r.nama_pelanggan}}/>:'-'}</td></tr>")
    .replace("colSpan={active.fields.length+1}", "colSpan={active.fields.length+2}")
    .replace("colSpan={(active?.fields?.length || 0) + 1}", "colSpan={(active?.fields?.length || 0) + 2}");
}

function personalizeNextPage(source) {
  return source
    .replace('PREMIUM NEXT.JS', "{APP.analysis?.uiDirection || 'BUSINESS OPERATIONS PLATFORM'}")
    .replace('Selamat datang', "{APP.analysis?.seoTitle || 'Kelola bisnis lebih tenang'}")
    .replace('Pengalaman baru yang lebih cepat dan modern.', "{APP.analysis?.summary || 'Satu workspace modern untuk memantau operasi, transaksi, dan pertumbuhan bisnis.'}")
    .replace("active?active.name:'Ringkasan bisnis'", "active?active.name:(APP.analysis?.seoTitle || 'Ringkasan bisnis')")
    .replace("active?'Kelola data dan aktivitas dari satu tempat.':'Pantau performa aplikasi secara real-time.'", "active?'Kelola data dan aktivitas dari satu tempat.':(APP.analysis?.summary || 'Pantau performa bisnis dari satu workspace yang terhubung.')")
    .replace('Demo lokal: Admin / Admin123', "{APP.analysis?.backendPlan || 'Workspace siap dikembangkan untuk kebutuhan operasional Anda.'}")
    .replace('className="login"', 'className={`login landing-${APP.design?.landing || \'split\'}`}')
    .replace('className="shell"', 'className={`shell layout-${APP.design?.layout || \'sidebar\'}`}')
    .replace("useEffect(()=>{try{setRows(JSON.parse(localStorage.getItem(storage)||'[]'))}catch{}},[]);", "useEffect(()=>{let live=true;fetch('/api/records').then(r=>r.ok?r.json():null).then(payload=>{if(live&&payload?.configured)setRows(payload.records||[])}).catch(()=>{try{if(live)setRows(JSON.parse(localStorage.getItem(storage)||'[]'))}catch{}});return()=>{live=false}},[]);")
    .replace('function save(e){', 'async function save(e){')
    .replace('localStorage.setItem(storage,JSON.stringify(next));e.currentTarget.reset()', "localStorage.setItem(storage,JSON.stringify(next));fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)}).catch(()=>{});e.currentTarget.reset()");
}

function personalizeMarketingPage(source) {
  return source
    .replace('className="marketing"', "className={`marketing landing-${APP.design?.landing || APP.analysis?.landingStyle || 'product'}`}")
    .replace("{APP.analysis?.seoTitle || 'Kelola operasi bisnis dengan lebih jelas.'}", "{APP.analysis?.landingHeadline || APP.analysis?.seoTitle || 'Kelola operasi bisnis dengan lebih jelas.'}")
    .replace('{APP.analysis?.summary || APP.profile.tagline}', '{APP.analysis?.landingDescription || APP.analysis?.summary || APP.profile.tagline}')
    .replace('Masuk ke workspace <span>→</span>', "{APP.analysis?.landingCta || 'Masuk ke workspace'} <span>→</span>");
}

function getPremiumNextPage() {
  return `'use client';
import { useEffect, useState } from 'react';
import { APP } from '../lib/app-config';

const storage = 'next-migration-records';
const money = value => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value)||0);

export default function Home() {
  const modules = APP.profile.modules || [];
  const [user,setUser] = useState(null);
  const [view,setView] = useState('dashboard');
  const [rows,setRows] = useState([]);
  const [theme,setTheme] = useState('dark');
  const [loginOpen,setLoginOpen] = useState(false);
  const active = modules.find(item => item.id === view);
  useEffect(() => { let live=true; fetch('/api/records').then(r=>r.ok?r.json():null).then(payload=>{if(live&&payload?.configured)setRows(payload.records||[])}).catch(()=>{try{if(live)setRows(JSON.parse(localStorage.getItem(storage)||'[]'))}catch{}}); return()=>{live=false}; }, []);
  useEffect(() => { document.documentElement.dataset.theme=theme; }, [theme]);
  function login(event) { event.preventDefault(); const form=new FormData(event.currentTarget); const name=form.get('username'); if(!name)return; setUser({name:name==='Admin'?'Administrator':name,role:name==='Admin'?'admin':'member'}); setLoginOpen(false); }
  async function save(event) { event.preventDefault(); if(!active)return; const data=Object.fromEntries(new FormData(event.currentTarget)); const next=[{id:crypto.randomUUID(),moduleId:active.id,createdAt:new Date().toLocaleString('id-ID'),...data},...rows]; setRows(next); localStorage.setItem(storage,JSON.stringify(next)); fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(next[0])}).catch(()=>{}); event.currentTarget.reset(); }
  if(!user) return <main className="marketing"><nav className="marketing-nav"><button className="wordmark" onClick={()=>setLoginOpen(true)}><span className="wordmark-mark">◈</span><span>{APP.name}</span></button><div className="nav-links"><a href="#fitur">Fitur</a><a href="#operasional">Operasional</a><a href="#siap">Siap digunakan</a></div><div className="nav-actions"><button className="text-button" onClick={()=>setLoginOpen(true)}>Masuk</button><button className="nav-cta" onClick={()=>setLoginOpen(true)}>Mulai sekarang <span>→</span></button></div></nav><section className="hero-saas"><div className="hero-copy"><p className="marketing-eyebrow">{APP.analysis?.uiDirection || 'PLATFORM OPERASIONAL BISNIS'}</p><h1>{APP.analysis?.seoTitle || 'Kelola operasi bisnis dengan lebih jelas.'}</h1><p className="hero-summary">{APP.analysis?.summary || APP.profile.tagline}</p><div className="hero-actions"><button className="primary-cta" onClick={()=>setLoginOpen(true)}>Masuk ke workspace <span>→</span></button><a className="secondary-cta" href="#fitur">Lihat kemampuan <span>↓</span></a></div><div className="trust-line"><span className="trust-dot"/>Dirancang untuk alur kerja yang cepat, rapi, dan mudah dipahami tim.</div></div><div className="hero-visual" aria-label="Pratinjau dashboard"><div className="visual-glow one"/><div className="visual-glow two"/><div className="preview-window"><div className="preview-top"><span className="preview-brand">{APP.profile.name}</span><span className="preview-live">Live workspace</span></div><div className="preview-body"><aside><span className="preview-logo">◈</span>{modules.slice(0,5).map((item,index)=><span className={index===0?'preview-nav active':'preview-nav'} key={item.id}>{item.name}</span>)}</aside><section><div className="preview-heading"><div><span>RINGKASAN HARI INI</span><b>Semua kendali dalam satu tempat</b></div><i/></div><div className="preview-stats"><article><small>Aktivitas</small><b>{rows.length}</b><span>tercatat</span></article><article><small>Nilai data</small><b>{money(rows.reduce((sum,row)=>sum+Number(row.total||row.nominal||row.harga||0),0))}</b><span>terpantau</span></article></div><div className="preview-chart"><div className="chart-title"><b>Aktivitas operasional</b><span>7 hari terakhir</span></div><div className="chart-bars"><i/><i/><i/><i/><i/><i/><i/></div></div></section></div></div><div className="floating-card"><span>✓</span><div><b>Siap untuk tim</b><small>Modul, data, dan laporan terstruktur</small></div></div></div></section><section id="fitur" className="feature-section"><div className="section-intro"><p className="marketing-eyebrow">DIRANCANG UNTUK PEKERJAAN NYATA</p><h2>Bukan sekadar dashboard. Ini adalah ruang kerja operasional Anda.</h2></div><div className="feature-grid"><article><span className="feature-icon">01</span><h3>Data yang terstruktur</h3><p>Modul disesuaikan dengan kebutuhan {APP.profile.name.toLowerCase()}, dari input inti hingga riwayat aktivitas.</p></article><article><span className="feature-icon">02</span><h3>Keputusan lebih cepat</h3><p>Ringkasan operasional membantu tim melihat aktivitas dan nilai pencatatan tanpa berpindah tempat.</p></article><article><span className="feature-icon">03</span><h3>Siap berkembang</h3><p>API dan skema PostgreSQL sudah disertakan untuk menghubungkan data produksi saat bisnis bertumbuh.</p></article></div></section><section id="operasional" className="operations-section"><div className="operations-copy"><p className="marketing-eyebrow">ALUR KERJA LEBIH TENANG</p><h2>Mulai dari satu proses, lalu satukan seluruh aktivitas bisnis.</h2><p>Setiap modul dibuat untuk memudahkan pencatatan, pelacakan, dan tindak lanjut tanpa membuat tim kewalahan.</p><button className="text-cta" onClick={()=>setLoginOpen(true)}>Buka workspace <span>→</span></button></div><div className="process-list">{['Catat data operasional secara konsisten','Pantau progres dan riwayat aktivitas','Siapkan data untuk laporan dan pengambilan keputusan'].map((item,index)=><article key={item}><span>0{index+1}</span><b>{item}</b><i>→</i></article>)}</div></section><section id="siap" className="closing-cta"><p className="marketing-eyebrow">MULAI DARI HAL YANG PENTING</p><h2>{APP.name} siap membantu pekerjaan harian terasa lebih terkontrol.</h2><button className="primary-cta" onClick={()=>setLoginOpen(true)}>Masuk ke dashboard <span>→</span></button></section>{loginOpen&&<div className="login-overlay" role="dialog" aria-modal="true"><form className="login-dialog" onSubmit={login}><button type="button" className="dialog-close" onClick={()=>setLoginOpen(false)} aria-label="Tutup">×</button><p className="marketing-eyebrow">AKSES WORKSPACE</p><h2>Selamat datang kembali.</h2><p>Masuk untuk mengelola {APP.profile.name.toLowerCase()} Anda.</p><label>Username<input name="username" defaultValue="Admin" required/></label><label>Password<input name="password" type="password" placeholder="Masukkan password" required/></label><button className="primary-cta">Masuk ke dashboard <span>→</span></button><small>Gunakan akun yang telah dibuat oleh Administrator.</small></form></div>}</main>;
  const nav = modules.filter(item => !item.adminOnly || user.role==='admin');
  const total = rows.reduce((sum,row)=>sum+Number(row.total||row.nominal||row.harga||0),0);
  return <main className={\`shell layout-\${APP.design?.layout || 'sidebar'}\`}><aside><div className="brand"><span className="brand-mark">◈</span><div><b>{APP.name}</b><small>{APP.profile.name}</small></div></div><nav><button className={view==='dashboard'?'active':''} onClick={()=>setView('dashboard')}>Dashboard</button>{nav.map(item=><button key={item.id} className={view===item.id?'active':''} onClick={()=>setView(item.id)}>{item.name}</button>)}</nav><div className="account"><span className="avatar">{user.name[0]}</span><div><b>{user.name}</b><small>{user.role==='admin'?'Administrator':'User'}</small></div><button aria-label="Keluar" onClick={()=>setUser(null)}>↪</button></div></aside><section className="workspace"><header><div><p className="eyebrow">{APP.profile.name}</p><h1>{active?active.name:(APP.analysis?.seoTitle || 'Ringkasan bisnis')}</h1><span>{active?'Kelola data dan aktivitas dari satu tempat.':(APP.analysis?.summary || 'Pantau performa bisnis dari satu workspace yang terhubung.')}</span></div><div className="header-actions"><button className="ghost" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?'Terang':'Gelap'}</button><button className="profile">{user.name[0]}</button></div></header>{!active?<Dashboard rows={rows} total={total} modules={modules} setView={setView}/>:<Module active={active} rows={rows.filter(row=>row.moduleId===active.id)} save={save}/>}<p className="notice">Database API tersedia saat POSTGRES_URL dikonfigurasi. Penyimpanan browser hanya dipakai sebagai fallback demo.</p></section></main>;
}

function Dashboard({rows,total,modules,setView}) { return <><section className="metrics"><article><small>Total aktivitas</small><b>{rows.length}</b><span>Semua modul</span></article><article><small>Nilai tercatat</small><b>{money(total)}</b><span>Akumulasi data</span></article><article><small>Modul aktif</small><b>{modules.length}</b><span>Siap digunakan</span></article></section><section className="overview"><article className="panel chart"><div className="panel-head"><div><p className="eyebrow">ANALITIK</p><h2>Aktivitas per modul</h2></div></div><div className="bars">{modules.map((item,index)=><button key={item.id} onClick={()=>setView(item.id)}><span style={{height:((rows.filter(row=>row.moduleId===item.id).length||1)/Math.max(rows.length,1)*100)+'%'}}/><small>{item.name}</small><b>{rows.filter(row=>row.moduleId===item.id).length}</b></button>)}</div></article><article className="panel recent"><div className="panel-head"><h2>Aktivitas terbaru</h2><span>{rows.length} data</span></div>{rows.slice(0,5).map(row=><div className="recent-row" key={row.id}><span className="pulse"/><div><b>{Object.values(row).find(value=>typeof value==='string'&&value!==row.createdAt&&value!==row.moduleId)||'Data baru'}</b><small>{row.createdAt}</small></div></div>)}{!rows.length&&<p className="empty">Belum ada aktivitas. Pilih menu untuk menambah data.</p>}</article></section></>; }

function Module({active,rows,save}) { return <section className="module-grid"><form className="panel form" onSubmit={save}><div className="panel-head"><div><p className="eyebrow">INPUT DATA</p><h2>Tambah {active.name}</h2></div></div>{active.fields.map(field=><label key={field.key}>{field.label}{field.type==='select'?<select name={field.key} required>{field.options.map(option=><option key={option}>{option}</option>)}</select>:<input name={field.key} type={field.type==='datetime-local'?'datetime-local':field.type} required/>}</label>)}<button>Simpan data <span>→</span></button></form><article className="panel records"><div className="panel-head"><div><p className="eyebrow">DATA TERBARU</p><h2>{active.name}</h2></div><span className="badge">{rows.length} data</span></div><div className="table-wrap"><table><thead><tr>{active.fields.map(field=><th key={field.key}>{field.label}</th>)}<th>Dibuat</th></tr></thead><tbody>{rows.length?rows.map(row=><tr key={row.id}>{active.fields.map(field=><td key={field.key}>{row[field.key]??'-'}</td>)}<td>{row.createdAt}</td></tr>):<tr><td colSpan={active.fields.length+1} className="empty">Belum ada data.</td></tr>}</tbody></table></div></article></section>; }
`;
}

